  function osIcon(os,cls='os-icon'){
    const k=osKey(os),a=`class="${cls}" viewBox="0 0 24 24" aria-hidden="true"`;
    if(k==='debian')return `<svg ${a}><use href="#atlas-os-debian"></use></svg>`;
    if(k==='ubuntu')return `<svg ${a}><use href="#atlas-os-ubuntu"></use></svg>`;
    if(k==='alpine')return `<svg ${a}><use href="#atlas-os-alpine"></use></svg>`;
    if(k==='arch')return `<svg ${a}><use href="#atlas-os-arch"></use></svg>`;
    if(k==='fedora')return `<svg ${a}><use href="#atlas-os-fedora"></use></svg>`;
    if(k==='centos')return `<svg ${a}><use href="#atlas-os-centos"></use></svg>`;
    if(k==='rocky')return `<svg ${a}><use href="#atlas-os-rocky"></use></svg>`;
    if(k==='suse')return `<svg ${a}><use href="#atlas-os-suse"></use></svg>`;
    return `<svg ${a}><use href="#atlas-os-linux"></use></svg>`
  }

  window.AtlasThemeIcons={flag:flagSvg,countryName};
  function money(node){if(!n(node.price))return '';const cycle={monthly:'/月',yearly:'/年',annual:'/年',quarterly:'/季',one_time:''}[node.billing_cycle]||'';return `${node.currency||'$'} ${n(node.price).toFixed(2)}${cycle}`}
  function when(v){if(!v)return '—';const d=new Date(v);return Number.isNaN(d.getTime())?'—':d.toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'})}
  const ALPHA2=/^[A-Z]{2}$/;
  class ApiError extends Error{constructor(status,message){super(message);this.status=status}}
  function safeMetrics(m){if(!m||typeof m!=='object')return null;const fields=['uptime','cpu','mem_total','mem_used','swap_total','swap_used','disk_total','disk_used','net_rx','net_tx','total_rx','total_tx','month_rx','month_tx','tcp','udp','procs'];for(const k of fields){if(typeof m[k]!=='number'||!Number.isFinite(m[k])||m[k]<0)return null}if(!Array.isArray(m.load)||m.load.length!==3||m.load.some(x=>typeof x!=='number'||!Number.isFinite(x)||x<0))return null;return m}
  function safeNodes(list){return Array.isArray(list)?list.filter(x=>x&&typeof x==='object').map(x=>{const metrics=safeMetrics(x.metrics),raw=String(x.country||'').trim().toUpperCase(),country=ALPHA2.test(raw)?raw:'';return metrics===x.metrics&&country===x.country?x:{...x,country,metrics}}):[]}
  async function api(path){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);try{const r=await fetch(`/api${path}`,{signal:controller.signal});if(!r.ok){const message=((await r.text()).slice(0,200)||r.statusText||`HTTP ${r.status}`);throw new ApiError(r.status,message)}return r.status===204?null:await r.json()}finally{clearTimeout(timer)}}
  function parseNodesFrame(raw){try{const nodes=JSON.parse(raw)?.nodes;return Array.isArray(nodes)?nodes:null}catch{return null}}
  function overviewProbeRank(name=''){const s=String(name||'').toLowerCase();if(s.includes('联通')||s.includes('unicom'))return 0;if(s.includes('电信')||s.includes('telecom'))return 1;if(s.includes('移动')||s.includes('cmcc')||s.includes('mobile'))return 2;return 10}
  function overviewProbeLabel(name=''){const s=String(name||'').trim();const l=s.toLowerCase();if(s.includes('联通')||l.includes('unicom'))return '联通';if(s.includes('电信')||l.includes('telecom'))return '电信';if(s.includes('移动')||l.includes('cmcc')||l.includes('mobile'))return '移动';return s.length>6?s.slice(0,6):s||'探针'}
  function summarizeOverviewPing(data){const rows=Array.isArray(data?.ping)?[...data.ping].sort((a,b)=>n(a.ts)-n(b.ts)):[],grouped=new Map();for(const p of rows){const id=String(p.task_id);if(!grouped.has(id))grouped.set(id,[]);grouped.get(id).push(p)}return [...grouped.entries()].map(([id,list])=>{const latest=list[list.length-1],name=data?.probes?.[id]||`Probe ${id}`,latency=latest?.latency==null?null:n(latest.latency),loss=Math.max(0,n(data?.loss?.[id],0));return {id,name,label:overviewProbeLabel(name),latency,loss,rank:overviewProbeRank(name)}}).sort((a,b)=>a.rank-b.rank||a.name.localeCompare(b.name)).slice(0,3)}
  function overviewPingEntry(node){return state.overviewPing.get(String(n(node.id)))}
  function latencyCellClass(value){if(value==null)return 'bad';if(value>=200)return 'bad';if(value>=120)return 'warn';return 'ok'}
  function lossCellClass(value){if(value==null)return 'idle';return value>0?'bad':'ok'}
  function compactLoss(value){const x=Math.max(0,n(value,0));return `${Number.isInteger(x)?x.toFixed(0):x.toFixed(1)}%`}
  function overviewPingStrip(node){const entry=overviewPingEntry(node);if(entry&&entry.items.length===0)return '';const items=entry?.items||[{id:'cu',label:'联通',loading:true},{id:'ct',label:'电信',loading:true},{id:'cm',label:'移动',loading:true}],loading=!entry;const cells=items.map(x=>{const pending=loading||x.loading,latency=pending?'—':x.latency==null?'超时':`${Math.round(x.latency)}ms`,loss=pending?'—':compactLoss(x.loss),latencyStatus=pending?'idle':latencyCellClass(x.latency),lossStatus=pending?'idle':lossCellClass(x.loss),title=pending?'正在获取网络状态':`${x.name||x.label} · 最近延迟 ${latency} · 1H 丢包率 ${loss}`;return `<div class="network-compact-item" title="${escapeHtml(title)}"><span class="network-provider">${escapeHtml(x.label)}</span><span class="network-compact-values"><b class="network-latency-value ${latencyStatus}">${escapeHtml(latency)}</b><i>·</i><b class="network-loss-value ${lossStatus}">${escapeHtml(loss)}</b></span></div>`}).join('');return `<div class="node-card-network ${loading?'is-loading':''}" data-ping-node="${n(node.id)}"><div class="network-compact-grid">${cells}</div></div>`}
  const overviewMarkup=new WeakMap();
  function patchOverviewPing(node){const id=n(node.id),card=document.querySelector(`.node-card-grid .node-card[data-node="${id}"]`);if(!card)return;const old=card.querySelector('.node-card-network'),html=overviewPingStrip(node);if(old&&overviewMarkup.get(old)===html)return;if(old){if(html)old.outerHTML=html;else old.remove()}else if(html)card.querySelector('.node-card-activity')?.insertAdjacentHTML('afterend',html);const current=card.querySelector('.node-card-network');if(current)overviewMarkup.set(current,html)}
  async function fetchOverviewPingNode(node,generation){try{const d=await api(`/nodes/${n(node.id)}/metrics?hours=1&points=60&series=ping`);if(generation!==state.overviewPingGeneration)return;state.overviewPing.set(String(n(node.id)),{items:summarizeOverviewPing(d),at:Date.now()});patchOverviewPing(node)}catch(e){if(generation!==state.overviewPingGeneration)return;if(e instanceof ApiError&&e.status===503)return;const key=String(n(node.id));if(!state.overviewPing.has(key))state.overviewPing.set(key,{items:[],at:Date.now(),error:true});patchOverviewPing(node)}}
  async function refreshOverviewPing(){if(document.hidden||state.overviewPingBusy||!state.nodes?.length||!document.querySelector('.node-card-grid'))return;state.overviewPingBusy=true;const generation=++state.overviewPingGeneration,nodes=sortedNodes();let cursor=0;async function worker(){while(generation===state.overviewPingGeneration){const index=cursor++;if(index>=nodes.length)break;await fetchOverviewPingNode(nodes[index],generation)}}try{await Promise.all(Array.from({length:Math.min(2,nodes.length)},worker))}finally{if(generation===state.overviewPingGeneration)state.overviewPingBusy=false}}
  function scheduleOverviewPing(){if(state.overviewPingTimer)clearInterval(state.overviewPingTimer);setTimeout(()=>{if(!document.hidden)refreshOverviewPing()},350);state.overviewPingTimer=setInterval(()=>{if(!document.hidden)refreshOverviewPing()},60000)}
  function nodeShape(list){return JSON.stringify([...(list||[])].sort((a,b)=>n(a.sort)-n(b.sort)||n(a.id)-n(b.id)).map(x=>[n(x.id),n(x.sort),String(x.name||''),String(x.country||''),String(x.os||''),String(x.arch||''),n(x.cpu_cores),String(x.virt||''),n(x.mem_total),n(x.disk_total),n(x.traffic_limit),String(x.traffic_mode||''),n(x.traffic_reset_day)]))}
  function regionSignature(nodes){const list=regions(nodes);return JSON.stringify([nodes.filter(x=>x.online).length,...list.map(x=>[x.code,x.count,x.online])])}
  function receiveNodes(list){if(!Array.isArray(list))throw new Error('节点数据格式异常');const next=safeNodes(list),shape=nodeShape(next),structureChanged=shape!==state.nodeShape;state.nodes=next;state.nodeShape=shape;sample(next);setErrorMessage('');liveRender(structureChanged)}
  async function refreshAccess(){try{const me=await api('/me');state.me=me;if(!me.public_page&&!me.authed)location.href='/admin/'}catch{}}

  const nodeViewport=matchMedia('(max-width:760px)');
  function activeNodeView(){return nodeViewport.matches?'card':(state.nodeView==='card'?'card':'list')}
  function rerenderNodePanel(){if(!state.nodes||!state.me)return;const panel=document.querySelector('.nodes-panel');if(!panel)return;const head=panel.querySelector('.panel-head'),headTop=head?.getBoundingClientRect().top,oldHeight=panel.getBoundingClientRect().height;panel.outerHTML=nodesPanel(sortedNodes());const next=document.querySelector('.nodes-panel');if(!next)return;next.style.minHeight=`${Math.ceil(oldHeight)}px`;requestAnimationFrame(()=>{const nextHead=next.querySelector('.panel-head');if(nextHead&&Number.isFinite(headTop)){const delta=nextHead.getBoundingClientRect().top-headTop;if(Math.abs(delta)>.5)scrollBy(0,delta)}requestAnimationFrame(()=>{next.style.minHeight=''})})}
  function viewportChanged(){rerenderNodePanel();if(activeNodeView()==='card')refreshOverviewPing();if(state.route!=null)renderDrawerContent(true)}
  if(nodeViewport.addEventListener)nodeViewport.addEventListener('change',viewportChanged);else nodeViewport.addListener?.(viewportChanged);

  function initialDark(){const saved=localStorage.getItem('atlas-theme');return saved?saved==='dark':matchMedia('(prefers-color-scheme: dark)').matches}
  function applyTheme(){document.documentElement.classList.toggle('dark',state.dark);document.querySelector('meta[name="theme-color"]')?.setAttribute('content',state.dark?'#11110f':'#f5f5f3')}
  function themeActionLabel(){return state.dark?'切换到浅色模式':'切换到深色模式'}
  function toggleTheme(){state.dark=!state.dark;localStorage.setItem('atlas-theme',state.dark?'dark':'light');applyTheme();const btn=document.querySelector('[data-action="theme"]');if(btn){btn.innerHTML=state.dark?ICONS.sun:ICONS.moon;const label=themeActionLabel();btn.title=label;btn.setAttribute('aria-label',label)}}
  applyTheme();
  function readRoute(){const m=location.pathname.match(/^\/node\/(\d+)\/?$/);return m?Number(m[1]):null}
  function routeTo(id){
    const next=id==null?null:Number(id);
    history.pushState({},'',next==null?'/':`/node/${next}`);
    state.route=next;state.detail.data=null;state.detail.error='';state.detail.hiddenProbes=[];state.detail.zoom=null;state.detail.drag=null;state.detail.mobileTab='ping';if(nodeViewport.matches)state.detail.tab='ping';
    if(next==null){closeDetailDrawer(false);document.title=`${state.me?.site_name||'Status'}`;return}
    showDetailDrawer();loadDetail();
  }
  addEventListener('popstate',()=>{
    state.route=readRoute();state.detail.data=null;state.detail.error='';state.detail.mobileTab='ping';if(nodeViewport.matches)state.detail.tab='ping';
    if(state.route==null){closeDetailDrawer(false);document.title=`${state.me?.site_name||'Status'}`}
    else{showDetailDrawer();loadDetail()}
  })

  function sample(nodes){const live=nodes.filter(x=>x.online&&x.metrics);state.speed.push({rx:live.reduce((s,x)=>s+x.metrics.net_rx,0),tx:live.reduce((s,x)=>s+x.metrics.net_tx,0)});if(state.speed.length>48)state.speed.shift()}
  function connectionNote(){const mode=state.connection;const text=mode==='ws'?'LIVE · WebSocket':mode==='poll'?'POLL · 5s':'RECONNECTING';return `<span class="panel-note live-mode ${mode}"><i class="presence-dot"></i>${text}</span>`}
  function setConnection(mode){if(state.connection===mode)return;state.connection=mode;const old=document.querySelector('.panel-note');if(old)old.outerHTML=connectionNote()}
