  function shell(content){const name=escapeHtml(state.me?.site_name||'Status');return `${osSprite()}<div class="shell"><header class="topbar"><div class="topbar-inner"><button class="brand" data-action="home"><span class="brand-mark"><img src="/assets/paper-plane.108f8147ac25.png" alt="" width="18" height="18"></span><span class="brand-text-wrap"><span class="brand-text">${name}</span></span></button><div class="top-actions"><button class="icon-btn" data-action="theme" title="${themeActionLabel()}" aria-label="${themeActionLabel()}">${state.dark?ICONS.sun:ICONS.moon}</button><a class="icon-btn admin-btn" href="/admin/" title="管理后台" aria-label="管理后台">${ICONS.sliders}</a></div></div></header><main class="main">${noticeHtml()}${content}</main><footer class="footer"><span>${escapeHtml(document.querySelector('meta[name="theme-version"]')?.content||'')}</span></footer></div>`}

  function summaryStats(nodes){const onlineNodes=nodes.filter(x=>x.online),live=onlineNodes.filter(x=>x.metrics),online=onlineNodes.length,offline=nodes.length-online,busiest=live.reduce((top,node)=>!top||n(node.metrics.cpu)>n(top.metrics.cpu)?node:top,null),busyCpu=busiest?n(busiest.metrics.cpu):0,dayRx=nodes.reduce((sum,x)=>sum+n(x.day_rx),0),dayTx=nodes.reduce((sum,x)=>sum+n(x.day_tx),0),totalRx=nodes.reduce((sum,x)=>sum+n(x.total_rx),0),totalTx=nodes.reduce((sum,x)=>sum+n(x.total_tx),0),now=state.speed.at(-1)||{rx:0,tx:0};return {online,offline,total:nodes.length,busiest,busyCpu,dayRx,dayTx,totalRx,totalTx,now}}
  function kpi(key,label,value,note,icon,extra='',cls=''){return `<article class="kpi ${cls}" data-kpi="${key}"><div class="kpi-label">${icon||''}${label}</div><div class="kpi-value ${String(value).length>13?'small':''}" data-kpi-value>${value}</div><div class="kpi-note" data-kpi-note>${note}</div>${extra}</article>`}
