  const sparkMarkup=new WeakMap();
  function patchKpis(nodes){const root=document.querySelector('.kpis');if(!root)return false;const s=summaryStats(nodes),set=(sel,value)=>patchText(root.querySelector(sel),value);set('[data-kpi="nodes"] [data-kpi-value]',`${s.online} / ${s.total}`);set('[data-kpi="nodes"] [data-kpi-note]',s.offline?`${s.offline} 个离线`:'全部在线');set('[data-kpi="busy"] [data-kpi-value]',s.busiest?`${s.busyCpu.toFixed(1)}%`:'—');set('[data-kpi="busy"] [data-kpi-note]',s.busiest?(s.busiest.name||`Node ${s.busiest.id}`):'无在线节点');set('[data-flow="day-down"]',bytes(s.dayRx));set('[data-flow="day-up"]',bytes(s.dayTx));set('[data-flow="total-down"]',bytes(s.totalRx));set('[data-flow="total-up"]',bytes(s.totalTx));set('[data-flow="speed-down"]',rate(s.now.rx));set('[data-flow="speed-up"]',rate(s.now.tx));const card=root.querySelector('[data-kpi="speed"]'),old=card?.querySelector('.summary-spark'),next=sparkPair();if(card&&sparkMarkup.get(card)!==next){if(next){if(old)old.outerHTML=next;else card.insertAdjacentHTML('beforeend',next)}else old?.remove();sparkMarkup.set(card,next)}return true}
  function meter(label,val,text,cls=''){const c=val>=90?'bad':val>=75?'warn':cls,v=clamp(val);return `<div class="metric"><div class="metric-top"><span>${label}</span><b>${escapeHtml(text)}</b></div><div class="bar ${c}"><span style="width:${v.toFixed(1)}%;background:${resourceBarGradient(v)}"></span></div></div>`}
