  function trafficUse(node){const used=monthUsage(node),limit=n(node.traffic_limit),remaining=limit>0?Math.max(0,limit-used):null,percent=limit>0?pct(used,limit):0,reset=trafficResetText(node),fill=limit>0?trafficBarGradient(percent):'var(--traffic-ok)';return `<div class="traffic"${limit>0?` title="月额度 ${escapeHtml(bytes(limit))}"`:''}><small class="list-traffic-label">流量${reset?`<em>${escapeHtml(reset)}</em>`:''}</small><div class="traffic-value"><span>${bytes(used)}</span><b>${limit>0?`${percent.toFixed(percent>=10?0:1)}%`:'∞'}</b></div>${limit>0?`<div class="bar traffic"><span style="width:${percent.toFixed(1)}%;background:${fill}"></span></div>`:''}<div class="traffic-sub">${remaining==null?'余量 ∞':`余量 ${quotaBytes(remaining)}`}</div></div>`}
