  function nodeRow(node){const m=node.metrics,online=!!node.online,cpu=m?clamp(m.cpu):0,mem=m?pct(m.mem_used,m.mem_total||node.mem_total):0,disk=m?pct(m.disk_used,m.disk_total||node.disk_total):0,country=String(node.country||'').trim().toUpperCase(),os=osLabel(node.os),extra=m?`Load ${m.load.map(x=>n(x).toFixed(2)).join(' ')}`:(country?'地区已识别':'地区待识别'),locationMark=country?`<span class="flag" title="${escapeHtml(countryName(country))} · ${country}">${flagSvg(country)}</span>`:`<span class="flag pending" title="地区待识别">◎</span>`,name=escapeHtml(node.name||`Node ${node.id}`);return `<div class="node ${online?'online':'offline'}" data-node="${n(node.id)}" data-action="node" data-id="${n(node.id)}" role="button" tabindex="0" aria-label="查看 ${name} 详情"><div class="node-main"><div class="identity">${locationMark}<div class="node-title"><div class="node-heading"><strong title="${name}">${name}</strong><span class="node-card-os list-node-os" title="${escapeHtml(os)}">${osIcon(node.os)}</span></div><div class="node-extra">${escapeHtml(extra||'—')}</div></div></div>${listCpuMeter(node,cpu,m)}${meter('RAM',mem,m?`${bytes(m.mem_used)} / ${bytes(m.mem_total||node.mem_total)}`:'—')}${meter('DISK',disk,m?`${bytes(m.disk_used)} / ${bytes(m.disk_total||node.disk_total)}`:'—')}<div class="net"><div><small>实时下行</small><span class="rx">${m?rate(m.net_rx):'—'}</span></div><div><small>实时上行</small><span class="tx">${m?rate(m.net_tx):'—'}</span></div>${trafficInline(node)}</div>${trafficUse(node)}<div class="runtime"><small>运行时间</small><span class="runtime-line"><i class="presence-dot"></i><span class="runtime-value">${m?uptime(m.uptime):(online?'等待上报':'离线')}</span></span><div class="runtime-sub">${online?`最后上报 ${age(node.last_seen)}`:age(node.last_seen)}</div></div><span class="node-open" aria-hidden="true">${ICONS.arrow}</span></div></div>`}


  function cardMeter(label,val,value,sub=''){const c=val>=90?'bad':val>=75?'warn':'',v=clamp(val);return `<div class="card-resource"><div class="card-resource-top"><span>${label}</span><b>${escapeHtml(value)}</b></div><div class="bar ${c}"><span style="width:${v.toFixed(1)}%;background:${resourceBarGradient(v)}"></span></div>${sub?`<div class="card-resource-sub">${escapeHtml(sub)}</div>`:''}</div>`}
  function cardCpuMeter(node,cpu,m,load){const c=cpu>=90?'bad':cpu>=75?'warn':'',spec=[node.arch,node.virt].filter(Boolean).join(' · '),value=m?`${node.cpu_cores?`${node.cpu_cores}C · `:''}${cpu.toFixed(1)}%`:(node.cpu_cores?`${node.cpu_cores}C · —`:'—'),v=clamp(cpu);return `<div class="card-resource card-resource-cpu"><div class="card-resource-top"><span class="card-resource-label">CPU${spec?`<em>${escapeHtml(spec)}</em>`:''}</span><b>${escapeHtml(value)}</b></div><div class="bar ${c}"><span style="width:${v.toFixed(1)}%;background:${resourceBarGradient(v)}"></span></div><div class="card-resource-sub">${escapeHtml(m?load:'等待指标')}</div></div>`}
