  function cardTraffic(node){const used=monthUsage(node),limit=n(node.traffic_limit),remaining=limit>0?Math.max(0,limit-used):null,percent=limit>0?pct(used,limit):0,reset=trafficResetText(node),fill=limit>0?trafficBarGradient(percent):'var(--traffic-ok)';return `<div class="card-resource card-traffic"${limit>0?` title="月额度 ${escapeHtml(bytes(limit))}"`:''}><div class="card-resource-top"><span class="card-traffic-label">流量${reset?`<em>${escapeHtml(reset)}</em>`:''}</span><b>${limit>0?`${percent.toFixed(percent>=10?0:1)}%`:'∞'}</b></div><div class="bar card-traffic-bar"><span style="width:${limit>0?percent.toFixed(1):0}%;background:${fill}"></span></div><div class="card-resource-sub">已用 ${bytes(used)} · 余 ${remaining==null?'∞':quotaBytes(remaining)}</div></div>`}
  function nodeCard(node){const m=node.metrics,online=!!node.online,cpu=m?clamp(m.cpu):0,mem=m?pct(m.mem_used,m.mem_total||node.mem_total):0,disk=m?pct(m.disk_used,m.disk_total||node.disk_total):0,country=String(node.country||'').trim().toUpperCase(),os=osLabel(node.os),name=escapeHtml(node.name||`Node ${node.id}`),locationMark=country?`<span class="flag" title="${escapeHtml(countryName(country))} · ${country}">${flagSvg(country)}</span>`:`<span class="flag pending" title="地区待识别">◎</span>`,load=m?`Load ${m.load.map(x=>n(x).toFixed(2)).join(' ')}`:'等待指标',totalRx=n(m?.total_rx||node.total_rx),totalTx=n(m?.total_tx||node.total_tx);return `<div class="node-card ${online?'online':'offline'}" data-node="${n(node.id)}" data-action="node" data-id="${n(node.id)}" role="button" tabindex="0" aria-label="查看 ${name} 详情"><div class="node-card-head"><div class="node-card-identity">${locationMark}<strong title="${name}">${name}</strong><span class="node-card-os" title="${escapeHtml(os)}">${osIcon(node.os)}</span></div><div class="node-card-runtime"><i class="presence-dot"></i><span class="runtime-value">${m?`在线 ${uptime(m.uptime)}`:(online?'在线 · 等待上报':'离线')}</span></div><span class="node-card-open" aria-hidden="true">${ICONS.arrow}</span></div><div class="node-card-resources">${cardCpuMeter(node,cpu,m,load)}${cardMeter('RAM',mem,m?`${mem.toFixed(0)}%`:'—',m?`${bytes(m.mem_used)} / ${bytes(m.mem_total||node.mem_total)}`:'—')}${cardMeter('DISK',disk,m?`${disk.toFixed(0)}%`:'—',m?`${bytes(m.disk_used)} / ${bytes(m.disk_total||node.disk_total)}`:'—')}${cardTraffic(node)}</div><div class="node-card-activity"><div><b class="rx">${m?rate(m.net_rx):'—'}</b><span>↓ ${m?bytes(totalRx):'—'}</span></div><div><b class="tx">${m?rate(m.net_tx):'—'}</b><span>↑ ${m?bytes(totalTx):'—'}</span></div></div>${overviewPingStrip(node)}</div>`}


  function regions(nodes){const map=new Map();for(const node of nodes){const code=String(node.country||'').trim().toUpperCase();if(!code)continue;const g=map.get(code)||{code,count:0,online:0};g.count++;if(node.online)g.online++;map.set(code,g)}return [...map.values()].sort((a,b)=>b.count-a.count||a.code.localeCompare(b.code))}
